print(len(S),len(Z))
def norm(s):
    s=unicodedata.normalize('NFKD',s.lower().replace('đ','d'))
    s=''.join(c for c in s if not unicodedata.combining(c))
    return re.sub(r'[^a-z0-9 ]','',s).split()
base='/tmp/claude-0/-home-claude/d0049d8f-34eb-5d03-b489-fe414f5ca31b/scratchpad/content/'
m=json.load(open(base+'merged.json'))['cats']
ex=[(k,x['q'],x['o'][x['a']]) for k,v in m.items() for x in v]
exq={' '.join(norm(q)) for _,q,_ in ex}
out={}
for name,L in (('Svemir',S),('Znanost',Z)):
    res=[];seen=set()
    for i,t in enumerate(L):
        q,opts=t[0],list(t[1:])
        assert len(opts)==4 and len(set(opts))==4,q
        if len(q)>110: print('LONGQ',len(q),q)
        for o in opts:
            if len(o)>30: print('LONGO',o)
        nq=' '.join(norm(q))
        if nq in exq or nq in seen: print('DUP',q); continue
        seen.add(nq)
        # similarity flag
        ws=set(w for w in norm(q) if len(w)>3)
        for k,eq,ea in ex:
            ew=set(w for w in norm(eq) if len(w)>3)
            if ws and len(ws&ew)/max(1,min(len(ws),len(ew)))>=0.6: print('SIM',q,'<->',eq)
            if ' '.join(norm(ea))==' '.join(norm(opts[0])) and len(ws&ew)>=2: print('ANS',q,'<->',eq)
        a=len(res)%4
        o=opts[1:]; o.insert(a,opts[0])
        res.append({"q":q,"o":o,"a":a})
    out[name]=res
json.dump({"cats":out},open(base+'r2_01.json','w'),ensure_ascii=False,indent=1)
print({k:len(v) for k,v in out.items()})
